app.get('/api/exams', async c => {
  let sql=`SELECT e.*,p.name publisher_name,p.short_name publisher_short,g.name grade_name,g.code grade_code FROM exams e JOIN publishers p ON p.id=e.publisher_id JOIN grade_levels g ON g.id=e.grade_level_id WHERE e.deleted_at IS NULL`; const vals:any[]=[];
  for(const [key,col] of [['season_id','e.season_id'],['grade_level_id','e.grade_level_id'],['publisher_id','e.publisher_id'],['exam_type','e.exam_type']] as any){const v=c.req.query(key);if(v){sql+=` AND ${col}=?`;vals.push(v)}}
  const month=c.req.query('month');if(month){sql+=` AND substr(e.application_start_date,6,2)=?`;vals.push(String(month).padStart(2,'0'))}
  const status=c.req.query('active');if(status==='1')sql+=' AND e.is_active=1';if(status==='0')sql+=' AND e.is_active=0';const q=c.req.query('q');if(q){sql+=` AND (e.name LIKE ? OR e.code LIKE ? OR p.name LIKE ?)`;vals.push(`%${q}%`,`%${q}%`,`%${q}%`)}sql+=' ORDER BY e.application_start_date,e.name';
  const r=await c.env.DB.prepare(sql).bind(...vals).all();return c.json({ok:true,items:r.results});
});
app.post('/api/exams', requireRoles('SUPER_ADMIN','ADMIN'), async c => { const x:any=await c.req.json(); if(!x.publisher_id||!x.season_id||!x.grade_level_id||!x.name||!x.code)return fail(c,'Yayınevi, sezon, sınıf, ad ve kod gerekli.'); const rid=uid('exam'); await c.env.DB.prepare(`INSERT INTO exams(id,publisher_id,season_id,grade_level_id,name,code,list_price,purchase_price,default_sale_price,minimum_order,last_order_date,estimated_ship_date,application_start_date,application_end_date,description,status,is_active,exam_type,subject,difficulty_level,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)`).bind(rid,x.publisher_id,x.season_id,x.grade_level_id,x.name,x.code,Number(x.list_price||0),Number(x.purchase_price||0),Number(x.default_sale_price||0),Number(x.minimum_order||1),x.last_order_date||null,x.estimated_ship_date||null,x.application_start_date||null,x.application_end_date||null,x.description||null,'ACTIVE',x.is_active===0?0:1,x.exam_type||'DENEME',x.subject||null,String(x.difficulty_level||'').trim()||null,now(),now()).run(); await audit(c.env.DB,c.get('user'),'CREATE','exam',rid,undefined,x);return c.json({ok:true,id:rid},201); });
app.post('/api/exams/bulk', requireRoles('SUPER_ADMIN','ADMIN'), async c => {const body:any=await c.req.json().catch(()=>({}));const rows:Array<any>=Array.isArray(body.rows)?body.rows:[];if(!rows.length)return fail(c,'Yüklenecek satır bulunamadı.');if(rows.length>2000)return fail(c,`Tek seferde en fazla 2000 sınav yüklenebilir. Gönderilen: ${rows.length}`);const season=String(body.season_id||'');if(!season)return fail(c,'Sezon seçimi gerekli.');const seasonExists=await c.env.DB.prepare(`SELECT id FROM seasons WHERE id=?`).bind(season).first();if(!seasonExists)return fail(c,'Sezon bulunamadı.',404);const canon=(v:any)=>String(v??'').trim().toLocaleUpperCase('tr-TR').replace(/\s+/g,' ').replace(/[^0-9A-ZÇĞİÖŞÜ]+/g,'');const dateVal=(v:any)=>{if(v===null||v===undefined||v==='')return null;if(typeof v==='number'&&Number.isFinite(v)){const d=new Date(Date.UTC(1899,11,30)+Math.round(v*86400000));return d.toISOString().slice(0,10)}const s=String(v).trim();let m=s.match(/^(\d{4})[-/.](\d{1,2})[-/.](\d{1,2})$/);if(m)return `${m[1]}-${m[2].padStart(2,'0')}-${m[3].padStart(2,'0')}`;m=s.match(/^(\d{1,2})[./-](\d{1,2})[./-](\d{2,4})$/);if(m){let y=m[3];if(y.length===2)y=`20${y}`;return `${y}-${m[2].padStart(2,'0')}-${m[1].padStart(2,'0')}`}return s};const num=(v:any,def=0)=>{if(v===null||v===undefined||v==='')return def;const n=Number(String(v).trim().replace(/\s/g,'').replace(',','.').replace(/[^0-9.-]/g,''));return Number.isFinite(n)?n:def};const activeVal=(v:any)=>{const x=String(v??'').trim().toLocaleLowerCase('tr-TR');return ['hayır','hayir','h','no','false','0','pasif'].includes(x)?0:1};const diffish=(v:any)=>/^(KOLAY|KOLAY[- ]?ORTA|ORTA|ORTA[- ]?(ÜST|UST|ZOR)|ZOR|YKS|MAARİF|MAARIF|TG)/i.test(String(v||'').trim());const [pubRes,gradeRes,existingRes]=await Promise.all([c.env.DB.prepare(`SELECT id,name,short_name FROM publishers WHERE deleted_at IS NULL`).all<any>(),c.env.DB.prepare(`SELECT id,name,code FROM grade_levels WHERE is_active=1`).all<any>(),c.env.DB.prepare(`SELECT id,code FROM exams WHERE season_id=? AND deleted_at IS NULL`).bind(season).all<any>()]);const pubMap=new Map<string,any>();for(const p of pubRes.results||[])for(const v of [p.id,p.name,p.short_name])if(v)pubMap.set(canon(v),p);const missing=new Map<string,{id:string,name:string}>();for(const x of rows){const raw=String(x.publisher||x.publisher_id||'').trim();if(!raw)continue;const k=canon(raw);if(!pubMap.has(k)&&!missing.has(k))missing.set(k,{id:uid('pub'),name:raw})}if(missing.size){const st=[...missing.values()].map(p=>c.env.DB.prepare(`INSERT INTO publishers(id,name,short_name,minimum_order,default_discount,delivery_days,is_active,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?)`).bind(p.id,p.name,p.name,1,0,14,1,now(),now()));for(let i=0;i<st.length;i+=50)await c.env.DB.batch(st.slice(i,i+50));for(const [k,p] of missing)pubMap.set(k,{id:p.id,name:p.name,short_name:p.name})}const gradeMap=new Map<string,any>();for(const g of gradeRes.results||[])for(const v of [g.id,g.name,g.code])if(v)gradeMap.set(canon(v),g);const existingMap=new Map<string,any>();for(const e of existingRes.results||[])existingMap.set(canon(e.code),e);const seen=new Map<string,number>(),errors:any[]=[],prepared:{row:number;stmt:any;update:boolean}[]=[];for(let i=0;i<rows.length;i++){const x:any=rows[i]||{},row=i+2;const pubRaw=String(x.publisher||x.publisher_id||'').trim(),gradeRaw=String(x.grade||x.grade_level||x.grade_level_id||'').trim(),name=String(x.name||'').trim(),code=String(x.code||'').trim();if(!pubRaw||!gradeRaw||!name||!code){errors.push({row,error:'Yayınevi, sınıf, deneme adı ve kod zorunludur.'});continue}const codeKey=canon(code);if(seen.has(codeKey)){errors.push({row,error:`Aynı dosyada tekrar eden kod: ${code} (ilk satır ${seen.get(codeKey)})`});continue}seen.set(codeKey,row);const pub=pubMap.get(canon(pubRaw)),grade=gradeMap.get(canon(gradeRaw));if(!pub){errors.push({row,error:`Yayınevi eşleştirilemedi: ${pubRaw}`});continue}if(!grade){errors.push({row,error:`Sınıf düzeyi eşleştirilemedi: ${gradeRaw}`});continue}let subject=String(x.subject||'').trim()||null;let difficulty=String(x.difficulty_level||x.difficulty||x.zorluk||x.zorluk_seviyesi||'').trim()||null;const examType=String(x.exam_type||'DENEME').trim()||'DENEME';if(!difficulty&&subject&&examType.toLocaleUpperCase('tr-TR')!=='DERS_SINAVI'&&diffish(subject)){difficulty=subject;subject=null}const old=existingMap.get(codeKey),rid=old?.id||uid('exam');const stmt=c.env.DB.prepare(`INSERT INTO exams(id,publisher_id,season_id,grade_level_id,name,code,list_price,purchase_price,default_sale_price,minimum_order,last_order_date,estimated_ship_date,application_start_date,application_end_date,status,is_active,exam_type,subject,difficulty_level,created_at,updated_at,deleted_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,'ACTIVE',?,?,?,?,?,?,NULL) ON CONFLICT(code,season_id) DO UPDATE SET publisher_id=excluded.publisher_id,grade_level_id=excluded.grade_level_id,name=excluded.name,list_price=excluded.list_price,purchase_price=excluded.purchase_price,default_sale_price=excluded.default_sale_price,minimum_order=excluded.minimum_order,last_order_date=excluded.last_order_date,estimated_ship_date=excluded.estimated_ship_date,application_start_date=excluded.application_start_date,application_end_date=excluded.application_end_date,status='ACTIVE',is_active=excluded.is_active,exam_type=excluded.exam_type,subject=excluded.subject,difficulty_level=excluded.difficulty_level,updated_at=excluded.updated_at,deleted_at=NULL`).bind(rid,pub.id,season,grade.id,name,code,Math.round(num(x.list_price)*100),Math.round(num(x.purchase_price)*100),Math.round(num(x.sale_price??x.default_sale_price)*100),Math.max(1,Math.round(num(x.minimum_order,1))),dateVal(x.last_order_date),dateVal(x.estimated_ship_date),dateVal(x.application_start_date),dateVal(x.application_end_date),activeVal(x.active),examType,subject,difficulty,old?old.created_at||now():now(),now());prepared.push({row,stmt,update:!!old})}let created=0,updated=0;for(let i=0;i<prepared.length;i+=80){const chunk=prepared.slice(i,i+80);try{const rr=await c.env.DB.batch(chunk.map(x=>x.stmt));rr.forEach((r:any,j:number)=>{if(r?.success===false){errors.push({row:chunk[j].row,error:r.error||'Veritabanı işlemi başarısız.'})}else chunk[j].update?updated++:created++})}catch(e){for(const item of chunk){try{await item.stmt.run();item.update?updated++:created++}catch(err){errors.push({row:item.row,error:String(err)})}}}}await audit(c.env.DB,c.get('user'),'BULK_IMPORT','exam',season,undefined,{rows:rows.length,created,updated,publishers_created:missing.size,errors:errors.length});return c.json({ok:true,created,updated,publishers_created:missing.size,errors});});
