app.get('/api/users', requireRoles('SUPER_ADMIN','ADMIN'), async c=>{const r=await c.env.DB.prepare(`SELECT id,email,login_code,full_name,role,status,institution_id,must_change_password,phone,notification_enabled,created_at FROM users WHERE deleted_at IS NULL ORDER BY CASE role WHEN 'SUPER_ADMIN' THEN 0 ELSE 1 END,full_name`).all();return c.json({ok:true,items:r.results})});
app.post('/api/users', requireRoles('SUPER_ADMIN','ADMIN'), async c=>{const b:any=await c.req.json();if(!b.full_name||!b.email||!b.password||!b.role)return fail(c,'Ad soyad, e-posta, şifre ve rol gerekli.');if(b.role==='SUPER_ADMIN')return fail(c,'Yeni Süper Admin oluşturulamaz.',403);if(String(b.password).length<8)return fail(c,'Geçici şifre en az 8 karakter olmalı.');const rid=uid('user');await c.env.DB.prepare(`INSERT INTO users(id,email,password_hash,full_name,role,status,institution_id,must_change_password,login_code,phone,notification_enabled,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)`).bind(rid,String(b.email).trim().toLowerCase(),await hashPassword(String(b.password)),b.full_name,b.role,b.status||'ACTIVE',b.institution_id||null,1,b.login_code?normalizeCode(b.login_code):null,b.phone||null,b.notification_enabled?1:0,now(),now()).run();await audit(c.env.DB,c.get('user'),'CREATE','user',rid,undefined,{...b,password:'***'});return c.json({ok:true,id:rid},201)});
app.patch('/api/users/:id', requireRoles('SUPER_ADMIN','ADMIN'), async c=>{const actor=c.get('user'),rid=c.req.param('id'),b:any=await c.req.json();const row=await c.env.DB.prepare(`SELECT * FROM users WHERE id=? AND deleted_at IS NULL`).bind(rid).first<any>();if(!row)return fail(c,'Kullanıcı bulunamadı.',404);if(row.role==='SUPER_ADMIN'){if(actor.role!=='SUPER_ADMIN'||actor.id!==row.id)return fail(c,'Süper Admin hesabı dokunulmazdır.',403);const keys=Object.keys(b).filter(k=>b[k]!==undefined);if(!b.password||keys.some(k=>k!=='password'))return fail(c,'Süper Admin hesabında yalnız şifre değiştirilebilir.',403);if(String(b.password).length<10)return fail(c,'Süper Admin şifresi en az 10 karakter olmalı.');await c.env.DB.prepare(`UPDATE users SET password_hash=?,must_change_password=0,updated_at=? WHERE id=?`).bind(await hashPassword(String(b.password)),now(),rid).run();await c.env.DB.prepare(`DELETE FROM sessions WHERE user_id=? AND id NOT IN (SELECT id FROM sessions WHERE user_id=? ORDER BY created_at DESC LIMIT 1)`).bind(rid,rid).run();await audit(c.env.DB,actor,'PASSWORD_CHANGE','user',rid);return c.json({ok:true,protected:true})}if(b.role==='SUPER_ADMIN')return fail(c,'Bir kullanıcı Süper Admin yapılamaz.',403);if(actor.id===row.id&&b.status==='PASSIVE')return fail(c,'Kendi hesabınızı pasife alamazsınız.',400);await c.env.DB.prepare(`UPDATE users SET full_name=?,email=?,role=?,status=?,institution_id=?,login_code=?,phone=?,notification_enabled=?,updated_at=? WHERE id=?`).bind(b.full_name??row.full_name,b.email===undefined?row.email:String(b.email).trim().toLowerCase(),b.role??row.role,b.status??row.status,b.institution_id===undefined?row.institution_id:b.institution_id,b.login_code===undefined?row.login_code:normalizeCode(b.login_code),b.phone===undefined?row.phone:b.phone,(b.notification_enabled===undefined?row.notification_enabled:(b.notification_enabled?1:0)),now(),rid).run();if(b.password){if(String(b.password).length<8)return fail(c,'Şifre en az 8 karakter olmalı.');await c.env.DB.prepare(`UPDATE users SET password_hash=?,must_change_password=1,updated_at=? WHERE id=?`).bind(await hashPassword(String(b.password)),now(),rid).run();await c.env.DB.prepare(`DELETE FROM sessions WHERE user_id=?`).bind(rid).run()}await audit(c.env.DB,actor,'UPDATE','user',rid,row,{...b,password:b.password?'***':undefined});return c.json({ok:true})});
app.delete('/api/users/:id', requireRoles('SUPER_ADMIN','ADMIN'), async c=>{const actor=c.get('user'),rid=c.req.param('id');const row=await c.env.DB.prepare(`SELECT * FROM users WHERE id=? AND deleted_at IS NULL`).bind(rid).first<any>();if(!row)return fail(c,'Kullanıcı bulunamadı.',404);if(row.role==='SUPER_ADMIN')return fail(c,'Süper Admin hesabı silinemez.',403);if(actor.id===row.id)return fail(c,'Kendi hesabınızı silemezsiniz.',400);await c.env.DB.prepare(`UPDATE users SET status='PASSIVE',deleted_at=?,updated_at=? WHERE id=?`).bind(now(),now(),rid).run();await c.env.DB.prepare(`DELETE FROM sessions WHERE user_id=?`).bind(rid).run();await audit(c.env.DB,actor,'DELETE','user',rid,row,undefined);return c.json({ok:true})});
app.get('/api/permissions/catalog', requireRoles('SUPER_ADMIN'), c=>c.json({ok:true,items:PERMISSION_CATALOG}));
app.get('/api/users/:id/permissions', requireRoles('SUPER_ADMIN'), async c=>{const rid=c.req.param('id'),row=await c.env.DB.prepare(`SELECT id,role FROM users WHERE id=? AND deleted_at IS NULL`).bind(rid).first<any>();if(!row)return fail(c,'Kullanıcı bulunamadı.',404);if(row.role==='SUPER_ADMIN')return c.json({ok:true,allowed:PERMISSION_CATALOG.map(x=>x.code),protected:true});const overrides=await c.env.DB.prepare(`SELECT permission_code,is_allowed FROM user_permission_overrides WHERE user_id=?`).bind(rid).all<any>();const allowed=new Set(ROLE_DEFAULTS[row.role]||[]);for(const x of overrides.results||[]){x.is_allowed?allowed.add(x.permission_code):allowed.delete(x.permission_code)}return c.json({ok:true,allowed:[...allowed]})});
app.put('/api/users/:id/permissions', requireRoles('SUPER_ADMIN'), async c=>{const actor=c.get('user'),rid=c.req.param('id'),body:any=await c.req.json().catch(()=>({})),row=await c.env.DB.prepare(`SELECT id,role FROM users WHERE id=? AND deleted_at IS NULL`).bind(rid).first<any>();if(!row)return fail(c,'Kullanıcı bulunamadı.',404);if(row.role==='SUPER_ADMIN')return fail(c,'Süper Admin yetkileri değiştirilemez.',403);const allowed=new Set(Array.isArray(body.allowed)?body.allowed:[]),valid=new Set(PERMISSION_CATALOG.map(x=>x.code));await c.env.DB.prepare(`DELETE FROM user_permission_overrides WHERE user_id=?`).bind(rid).run();const stmts:any[]=[];for(const code of valid){stmts.push(c.env.DB.prepare(`INSERT INTO user_permission_overrides(user_id,permission_code,is_allowed,updated_by,updated_at) VALUES(?,?,?,?,?)`).bind(rid,code,allowed.has(code)?1:0,actor.id,now()))}if(stmts.length)await c.env.DB.batch(stmts);await audit(c.env.DB,actor,'UPDATE','user_permissions',rid,undefined,{allowed:[...allowed]});return c.json({ok:true})});
app.get('/api/tasks', async c=>{const u=c.get('user'),all=c.req.query('scope')==='all'&&u.role==='SUPER_ADMIN';let sql=`SELECT t.*,a.full_name assigned_name,cr.full_name created_by_name FROM tasks t LEFT JOIN users a ON a.id=t.assigned_to LEFT JOIN users cr ON cr.id=t.created_by WHERE 1=1`;const vals:any[]=[];if(!all){sql+=' AND t.assigned_to=?';vals.push(u.id)}sql+=' ORDER BY CASE t.status WHEN \'OPEN\' THEN 0 ELSE 1 END,CASE t.priority WHEN \'URGENT\' THEN 0 WHEN \'HIGH\' THEN 1 ELSE 2 END,t.due_date';const r=await c.env.DB.prepare(sql).bind(...vals).all();return c.json({ok:true,items:r.results})});
app.post('/api/tasks', requireRoles('SUPER_ADMIN'), async c=>{const u=c.get('user'),body:any=await c.req.json();if(!body.title||!body.assigned_to)return fail(c,'Görev ve kullanıcı gerekli.');const target=await c.env.DB.prepare(`SELECT id FROM users WHERE id=? AND role!='SUPER_ADMIN' AND status='ACTIVE' AND deleted_at IS NULL`).bind(body.assigned_to).first();if(!target)return fail(c,'Görev atanacak kullanıcı bulunamadı.');const rid=uid('task');await c.env.DB.prepare(`INSERT INTO tasks(id,title,description,assigned_to,created_by,due_date,status,priority,created_at,updated_at) VALUES(?,?,?,?,?,?,'OPEN',?,?,?)`).bind(rid,body.title,body.description||null,body.assigned_to,u.id,body.due_date||null,body.priority||'MEDIUM',now(),now()).run();await c.env.DB.prepare(`INSERT INTO notifications(id,user_id,type,title,message,related_id,is_read,created_at) VALUES(?,?,?,?,?,?,0,?)`).bind(uid('notice'),body.assigned_to,'TASK','Yeni görev atandı',body.title,rid,now()).run();return c.json({ok:true,id:rid},201)});
app.patch('/api/tasks/:id', async c=>{const u=c.get('user'),rid=c.req.param('id'),body:any=await c.req.json(),row=await c.env.DB.prepare(`SELECT * FROM tasks WHERE id=?`).bind(rid).first<any>();if(!row)return fail(c,'Görev bulunamadı.',404);if(u.role!=='SUPER_ADMIN'&&row.assigned_to!==u.id)return fail(c,'Yetkisiz.',403);if(u.role!=='SUPER_ADMIN'&&Object.keys(body).some(k=>!['status'].includes(k)))return fail(c,'Yalnız görev durumunu değiştirebilirsiniz.',403);await c.env.DB.prepare(`UPDATE tasks SET title=?,description=?,assigned_to=?,due_date=?,priority=?,status=?,completed_at=?,updated_at=? WHERE id=?`).bind(body.title??row.title,body.description===undefined?row.description:body.description,body.assigned_to??row.assigned_to,body.due_date===undefined?row.due_date:body.due_date,body.priority??row.priority,body.status??row.status,(body.status??row.status)==='DONE'?(row.completed_at||now()):null,now(),rid).run();return c.json({ok:true})});
app.get('/api/notifications', async c=>{const u=c.get('user'),r=await c.env.DB.prepare(`SELECT * FROM notifications WHERE user_id=? ORDER BY is_read ASC,created_at DESC LIMIT 50`).bind(u.id).all();return c.json({ok:true,items:r.results})});
app.patch('/api/notifications/:id/read', async c=>{const u=c.get('user'),rid=c.req.param('id');await c.env.DB.prepare(`UPDATE notifications SET is_read=1,read_at=? WHERE id=? AND user_id=?`).bind(now(),rid,u.id).run();return c.json({ok:true})});
app.get('/api/me/notification-settings', async c=>{const u=c.get('user'),row=await c.env.DB.prepare(`SELECT phone,notification_enabled FROM users WHERE id=?`).bind(u.id).first<any>();return c.json({ok:true,phone:row?.phone||'',notification_enabled:!!row?.notification_enabled,phone_provider_configured:!!c.env.PHONE_NOTIFICATION_WEBHOOK_URL})});
app.patch('/api/me/notification-settings', async c=>{const u=c.get('user'),body:any=await c.req.json();const phone=String(body.phone||'').trim();if(body.notification_enabled&&!phone)return fail(c,'Telefon bildirimi için telefon numarası gerekli.');await c.env.DB.prepare(`UPDATE users SET phone=?,notification_enabled=?,updated_at=? WHERE id=?`).bind(phone||null,body.notification_enabled?1:0,now(),u.id).run();return c.json({ok:true,phone_provider_configured:!!c.env.PHONE_NOTIFICATION_WEBHOOK_URL})});
app.post('/api/reminders/generate', requireRoles('SUPER_ADMIN'), async c=>{const r=await generateExamReminders(c.env);return c.json({ok:true,...r})});

app.get('/api/seasons', async c=>{const r=await c.env.DB.prepare(`SELECT * FROM seasons ORDER BY year_start DESC`).all();return c.json({ok:true,items:r.results})});
app.post('/api/seasons', requireRoles('SUPER_ADMIN','ADMIN'), async c=>{const b:any=await c.req.json();if(!b.name||!b.year_start||!b.year_end)return fail(c,'Sezon bilgileri gerekli.');if(Number(b.year_end)<=Number(b.year_start))return fail(c,'Bitiş yılı başlangıç yılından büyük olmalı.');if(b.is_active)await c.env.DB.prepare(`UPDATE seasons SET is_active=0`).run();const rid=uid('season');await c.env.DB.prepare(`INSERT INTO seasons(id,name,year_start,year_end,is_active,created_at,updated_at) VALUES(?,?,?,?,?,?,?)`).bind(rid,b.name,Number(b.year_start),Number(b.year_end),b.is_active?1:0,now(),now()).run();await audit(c.env.DB,c.get('user'),'CREATE','season',rid,undefined,b);return c.json({ok:true,id:rid},201)});
app.patch('/api/seasons/:id', requireRoles('SUPER_ADMIN','ADMIN'), async c=>{const rid=c.req.param('id'),b:any=await c.req.json();const row=await c.env.DB.prepare(`SELECT * FROM seasons WHERE id=?`).bind(rid).first<any>();if(!row)return fail(c,'Sezon bulunamadı.',404);const ys=Number(b.year_start??row.year_start),ye=Number(b.year_end??row.year_end);if(ye<=ys)return fail(c,'Bitiş yılı başlangıç yılından büyük olmalı.');if(b.is_active===true)await c.env.DB.prepare(`UPDATE seasons SET is_active=0 WHERE id<>?`).bind(rid).run();await c.env.DB.prepare(`UPDATE seasons SET name=?,year_start=?,year_end=?,is_active=?,updated_at=? WHERE id=?`).bind(b.name??row.name,ys,ye,b.is_active===undefined?row.is_active:(b.is_active?1:0),now(),rid).run();await audit(c.env.DB,c.get('user'),'UPDATE','season',rid,row,b);return c.json({ok:true})});

async function generateExamReminders(env:Env){await ensure(env.DB);const exams=await env.DB.prepare(`SELECT e.id,e.name,e.last_order_date,g.name grade_name,p.name publisher_name FROM exams e JOIN grade_levels g ON g.id=e.grade_level_id JOIN publishers p ON p.id=e.publisher_id WHERE e.is_active=1 AND e.deleted_at IS NULL AND e.last_order_date BETWEEN date('now') AND date('now','+7 day') ORDER BY e.last_order_date`).all<any>();let created=0,phoneSent=0;for(const ex of exams.results||[]){const days=Math.round((new Date(`${ex.last_order_date}T12:00:00Z`).getTime()-new Date(`${today()}T12:00:00Z`).getTime())/86400000);if(![0,1,3,7].includes(days))continue;const kind=days===0?'SON_GUN':`SON_SIPARIS_${days}G`,title=days===0?'Bugün son sipariş günü':`Son siparişe ${days} gün kaldı`,message=`${ex.publisher_name} · ${ex.grade_name} · ${ex.name} — son sipariş ${ex.last_order_date}`;const recipients=await env.DB.prepare(`SELECT DISTINCT u.id,u.phone,u.notification_enabled FROM users u WHERE u.status='ACTIVE' AND u.deleted_at IS NULL AND (u.role='SUPER_ADMIN' OR (u.role='ADMIN') OR (u.role='PERSONEL' AND EXISTS(SELECT 1 FROM institution_exam_plans ip JOIN institutions i ON i.id=ip.institution_id WHERE ip.exam_id=? AND i.staff_id=u.id)))`).bind(ex.id).all<any>();for(const user of recipients.results||[]){const rid=uid('rem');try{const ins=await env.DB.prepare(`INSERT OR IGNORE INTO reminder_delivery_log(id,user_id,exam_id,reminder_type,reminder_date,channel,status,created_at) VALUES(?,?,?,?,?,'IN_APP','CREATED',?)`).bind(rid,user.id,ex.id,kind,today(),now()).run();if(Number((ins.meta as any)?.changes||0)>0){await env.DB.prepare(`INSERT INTO notifications(id,user_id,type,title,message,related_id,is_read,created_at) VALUES(?,?,?,?,?,?,0,?)`).bind(uid('notice'),user.id,'EXAM_DEADLINE',title,message,ex.id,now()).run();created++}}catch{}if(user.notification_enabled&&user.phone&&env.PHONE_NOTIFICATION_WEBHOOK_URL){const logId=uid('rem');try{const check=await env.DB.prepare(`SELECT id FROM reminder_delivery_log WHERE user_id=? AND exam_id=? AND reminder_type=? AND reminder_date=? AND channel='PHONE'`).bind(user.id,ex.id,kind,today()).first();if(!check){const res=await fetch(env.PHONE_NOTIFICATION_WEBHOOK_URL,{method:'POST',headers:{'Content-Type':'application/json',...(env.PHONE_NOTIFICATION_WEBHOOK_TOKEN?{'Authorization':`Bearer ${env.PHONE_NOTIFICATION_WEBHOOK_TOKEN}`}:{})},body:JSON.stringify({phone:user.phone,title,message,type:kind,exam_id:ex.id})});await env.DB.prepare(`INSERT INTO reminder_delivery_log(id,user_id,exam_id,reminder_type,reminder_date,channel,status,provider_response,created_at) VALUES(?,?,?,?,?,'PHONE',?,?,?)`).bind(logId,user.id,ex.id,kind,today(),res.ok?'SENT':'FAILED',String(res.status),now()).run();if(res.ok)phoneSent++}}catch(e:any){await env.DB.prepare(`INSERT OR IGNORE INTO reminder_delivery_log(id,user_id,exam_id,reminder_type,reminder_date,channel,status,provider_response,created_at) VALUES(?,?,?,?,?,'PHONE','FAILED',?,?)`).bind(logId,user.id,ex.id,kind,today(),String(e?.message||e),now()).run()}}}}return{created,phone_sent:phoneSent,provider_configured:!!env.PHONE_NOTIFICATION_WEBHOOK_URL}}

export default {fetch:app.fetch,scheduled:async(_controller:any,env:Env,ctx:any)=>{ctx.waitUntil(generateExamReminders(env))}};

